const T1 = 1.2, T2 = 3.0, BURST = .5;       // 글리치가 시작하는 시각 · 길이(초)
const inBurst = (t >= T1 && t < T1 + BURST) || (t >= T2 && t < T2 + BURST);
if (!inBurst) ctx.drawImage(base, 0, 0);   // 그 밖에는 원본 그대로

const SPLIT = 14;                                  // 어긋나는 거리(px)
ctx.fillStyle = '#000'; ctx.fillRect(0, 0, W, H);
ctx.globalCompositeOperation = 'lighter';          // 더하기 합성
ctx.drawImage(red,   -SPLIT * 2, 0);               // 캔버스는 2배 크기
ctx.drawImage(green,  0, 0);
ctx.drawImage(blue,   SPLIT * 2, 0);

const step = Math.floor(t * 12);                   // 초당 12번만 값이 바뀜
for (let i = 0; i < 16; i++) {
  const dx = rand(step, i) > .55 ? (rand(step, i + 40) - .5) * 2 * TEAR : 0;
  ctx.drawImage(layer, 0, i * bh, W, bh, dx, i * bh, W, bh);
}
for (let y = 0; y < H; y += 4) ctx.fillRect(0, y, W, 2);   // 주사선
